function getUser(id) {
  return new Promise((resolve) =>
    setTimeout(() => resolve({ id, name: 'User ' + id }), 200)
  );
}

async function loadUsers(ids) {
  return Promise.all(ids.map((id) => getUser(id)));
}

loadUsers([1, 2, 3]).then((users) => console.log(users));

