function getUser() {
  return new Promise((resolve) =>
    setTimeout(() => resolve({ name: 'Ada' }), 100)
  );
}

async function show() {
  const user = await getUser();
  console.log(user.name); // 'Ada'
}

show();

async function retry(fn, attempts) {
  let lastError;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}
